 static void Split(List<Vector3> p,Func<Vector3,float> distance,out List<Vector3> inside,out List<Vector3> outside){inside=new List<Vector3>();outside=new List<Vector3>();if(p.Count==0)return;var a=p.Last();float da=distance(a);foreach(var b in p){float db=distance(b);if((da>=0)!=(db>=0)){var v=Vector3.Lerp(a,b,da/(da-db));inside.Add(v);outside.Add(v);}if(db>=0)inside.Add(b);else outside.Add(b);a=b;da=db;}}
