 static void KeepSource(Builder build,Mesh source,Segment[] cuts){var vs=source.vertices.Select(p=>build.tr.TransformPoint(p)).ToArray();for(int sub=0;sub<source.subMeshCount;sub++){var ids=source.GetTriangles(sub);for(int i=0;i<ids.Length;i+=3){var remains=new List<List<Vector3>>{new List<Vector3>{vs[ids[i]],vs[ids[i+1]],vs[ids[i+2]]}};foreach(var cut in cuts){var next=new List<List<Vector3>>();var planes=new Func<Vector3,float>[]{p=>Height-p.y,p=>p.y+.001f,p=>Vector3.Dot(p,build.lateral)-cut.lo,p=>cut.hi-Vector3.Dot(p,build.lateral),p=>Vector3.Dot(p,build.normal)-cut.edge+.64f,p=>cut.edge+.01f-Vector3.Dot(p,build.normal)};foreach(var poly in remains){var inside=poly;foreach(var plane in planes){Split(inside,plane,out var inner,out var outer);if(outer.Count>=3)next.Add(outer);inside=inner;if(inside.Count<3)break;}}remains=next;}foreach(var poly in remains)build.Poly(poly,sub);}}}
 static void Profile(Builder b,List<Vector2> shape,float back,float front,int mat){var face=shape.Select(p=>b.P(p.x,p.y,front)).ToList();if(Vector3.Dot(Vector3.Cross(face[1]-face[0],face[2]-face[0]),b.normal)<0)face.Reverse();b.Poly(face,mat);var rear=shape.Select(p=>b.P(p.x,p.y,back)).ToList();if(Vector3.Dot(Vector3.Cross(rear[1]-rear[0],rear[2]-rear[0]),b.normal)>0)rear.Reverse();b.Poly(rear,mat);for(int i=0;i<shape.Count;i++){var a=shape[i];var c=shape[(i+1)%shape.Count];var side=b.lateral*(c.y-a.y)-Vector3.up*(c.x-a.x);b.Quad(b.P(a.x,a.y,back),b.P(c.x,c.y,back),b.P(c.x,c.y,front),b.P(a.x,a.y,front),mat,side);}}
 static void Arch(Builder b,Opening h){float c=(h.a+h.b)/2,r=(h.b-h.a)/2,t=.1f,s=h.top-r;var glass=new List<Vector2>{new Vector2(h.a+t,h.bottom+t),new Vector2(h.b-t,h.bottom+t)};for(int k=0;k<=16;k++){float a=k*Mathf.PI/16;glass.Add(new Vector2(c+(r-t)*Mathf.Cos(a),s+(r-t)*Mathf.Sin(a)));}Profile(b,glass,-.465f,-.42f,1);
