 for(int k=0;k<16;k++){float a=k*Mathf.PI/16,z=(k+1)*Mathf.PI/16;Profile(b,new List<Vector2>{new Vector2(c+(r-t)*Mathf.Cos(a),s+(r-t)*Mathf.Sin(a)),new Vector2(c+r*Mathf.Cos(a),s+r*Mathf.Sin(a)),new Vector2(c+r*Mathf.Cos(z),s+r*Mathf.Sin(z)),new Vector2(c+(r-t)*Mathf.Cos(z),s+(r-t)*Mathf.Sin(z))},-.5f,-.08f,3);}
