 static void Infill(Builder b,float left,float right,Opening[] holes){
var xs=holes.SelectMany(h=>new[]{h.a,h.b}).Concat(new[]{left,right}).OrderBy(x=>x).Distinct().ToArray();var ys=holes.SelectMany(h=>new[]{h.bottom,h.top}).Concat(new[]{0f,.22f,Height}).OrderBy(y=>y).Distinct().ToArray();
var solid=new bool[xs.Length-1,ys.Length-1];for(int i=0;i<xs.Length-1;i++)for(int j=0;j<ys.Length-1;j++){float x=(xs[i]+xs[i+1])/2,y=(ys[j]+ys[j+1])/2;solid[i,j]=!holes.Any(h=>x>h.a&&x<h.b&&y>h.bottom&&y<h.top);}
for(int i=0;i<xs.Length-1;i++)for(int j=0;j<ys.Length-1;j++){if(!solid[i,j])continue;float l=xs[i],r=xs[i+1],d=ys[j],u=ys[j+1];int m=(u+d)/2<.22f?2:0;
