 float leftStart=lo+.5f,leftEnd=door-dw/2-.35f,rightStart=door+dw/2+.35f,rightEnd=hi-.5f;foreach(var span in new[]{new Vector2(leftStart,leftEnd),new Vector2(rightStart,rightEnd)}){float available=span.y-span.x;if(available<.55f)continue;float ww=Mathf.Min(available,shop?3.5f:2.4f);holes.Add(new Opening((span.x+span.y)/2,ww,shop?.38f:width<5?1.12f:.98f,shop?2.18f:width<5?1.10f:1.35f));}return holes.ToArray();}
