 var materials=oldMaterials.Take(4).ToList();materials.Add(Map.GetComponentsInChildren<Renderer>().SelectMany(v=>v.sharedMaterials).First(m=>m!=null&&m.name=="KIT_DistrictWall_A9B5A1"));var b=new Builder(r.transform,edge,normal,materials.Count);KeepSource(b,source,segments);
 var anchor=anchors.FirstOrDefault(v=>(string)v["building"]==id);float door=anchor!=null?Vector3.Dot(new Vector3((float)anchor["position"][0],0,(float)anchor["position"][2]),lateral):(segments[0].lo+segments[0].hi)/2;bool shop=id=="E01"||id=="E06"||id=="E12",arch=id=="E04"||id=="E10";int entrance=Enumerable.Range(0,segments.Length).OrderBy(i=>Mathf.Abs(Mathf.Clamp(door,segments[i].lo,segments[i].hi)-door)).First();if(anchor==null)door=segments[entrance].hi-(shop?1.4f:1.05f);
