 var mesh=b.Mesh(id+"_GroundFloor");f.sharedMesh=mesh;collider.sharedMesh=mesh;r.sharedMaterials=materials.ToArray();Physics.SyncTransforms();try{if(Mathf.Abs(r.bounds.max.y-oldBounds.max.y)>.01f||Mathf.Abs(r.bounds.min.y-oldBounds.min.y)>.01f)throw new Exception("Building height changed");foreach(var a in anchors.Where(v=>(string)v["building"]==id)){var p=new Vector3((float)a["position"][0],(float)a["position"][1],(float)a["position"][2]);if(Physics.OverlapCapsule(p+Vector3.up*.65f,p+Vector3.up*1.5f,.5f,~0,QueryTriggerInteraction.Ignore).Any(c=>c==collider))throw new Exception("Facade blocks anchor "+a["name"]);}if(existing==null)AssetDatabase.CreateAsset(mesh,path);else{existing.Clear();existing.indexFormat=IndexFormat.UInt32;existing.vertices=mesh.vertices;existing.subMeshCount=mesh.subMeshCount;for(int sub=0;sub<mesh.subMeshCount;sub++)existing.SetTriangles(mesh.GetTriangles(sub),sub);existing.RecalculateNormals();existing.RecalculateBounds();UnityEngine.Object.DestroyImmediate(mesh);mesh=existing;f.sharedMesh=mesh;collider.sharedMesh=null;collider.sharedMesh=mesh;EditorUtility.SetDirty(mesh);}}catch{f.sharedMesh=old;collider.sharedMesh=old;r.sharedMaterials=oldMaterials;UnityEngine.Object.DestroyImmediate(mesh);throw;}
